#ifndef WORLDWALKER_RUNTIME_BOATWATER_H
#define WORLDWALKER_RUNTIME_BOATWATER_H

#include <cstdint>

namespace ww::runtime
{
    // The tiles a rowing boat crosses: Lake Mnemosyne round the City of Um,
    // rowed in Ed's boat during The Spirit of War. The cache marks none of it
    // as water and the bake blocks it as void, so walking plans treat it as
    // solid; the table (BoatWaterRuns.inc, generated by
    // tools/boat_water/gen_boat_water.py from the cache's terrain) is the only
    // place the lake exists. A player standing on one of these tiles is in a
    // boat, since nothing else stands there.
    namespace boat_water
    {
        // True when (x, y, plane) is rowable lake water.
        bool isWater(int32_t x, int32_t y, int32_t plane);

        // True inside the box the table covers on its plane: while a boat is
        // rowed every tile in it is either water or shore the boat cannot
        // cross.
        bool covers(int32_t x, int32_t y, int32_t plane);

        // The water tile nearest (x, y) by Chebyshev distance, at most `reach`
        // tiles away, on the tile's plane; the first found on the nearest ring
        // (rows from south to north, then west to east). False, outputs
        // untouched, when none is that near.
        bool nearestWater(int32_t x, int32_t y, int32_t plane, int32_t reach,
                          int32_t &outX, int32_t &outY);
    }
}

#endif  // WORLDWALKER_RUNTIME_BOATWATER_H
